def dfs(start_state):
    # Check if the start state is already in a group
    for group_id in groups:
        for s in groups[group_id]:
            if s == start_state:
                return group_id

    # Create a new group for the start state
    group_id = len(groups)
    groups[group_id] = [start_state]

    # Perform DFS to expand the group
    stack = [(start_state, None)]
    while stack:
        (state, parent) = stack.pop()
        if parent is not None and parent != goal:
            for movement in movements:
                next_state = (state[0] + movement[0], state[1] + movement[1])
